static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *cov_array;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &cov_array))
        return NULL;

    if (PyArray_NDIM(weights_array) != 1 || PyArray_TYPE(weights_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "weights must be a 1D float64 array");
        return NULL;
    }
    if (PyArray_NDIM(cov_array) != 2 || PyArray_TYPE(cov_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "cov_matrix must be a 2D float64 array");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError, "array dimensions do not match");
        return NULL;
    }

    const double *w = (const double *)PyArray_DATA(weights_array);
    const double *cov = (const double *)PyArray_DATA(cov_array);

    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (temp == NULL) {
        PyErr_NoMemory();
        return NULL;
    }

    for (npy_intp i = 0; i < n; i++) {
        const double *row = cov + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; j++) {
            row_sum += row[j] * w[j];
        }
        temp[i] = row_sum;
    }

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        risk_squared += w[i] * temp[i];
    }

    free(temp);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *returns_array;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &returns_array))
        return NULL;

    if (PyArray_NDIM(weights_array) != 1 || PyArray_TYPE(weights_array) != NPY_DOUBLE ||
        PyArray_NDIM(returns_array) != 1 || PyArray_TYPE(returns_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "weights and returns must be 1D float64 arrays");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) != n) {
        PyErr_SetString(PyExc_ValueError, "array dimensions do not match");
        return NULL;
    }

    const double *w = (const double *)PyArray_DATA(weights_array);
    const double *r = (const double *)PyArray_DATA(returns_array);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        total_return += w[i] * r[i];
    }

    return PyFloat_FromDouble(total_return);
}

